import {analyze} from './recommendations.js';
let uploaded=null,scale=null,mode='scale',points=[],boxes={},root,state,helpers,observer;
const $=selector=>root.querySelector(selector);
export function renderPlanner(container,appState,services){root=container;state=appState;helpers=services;const {esc,icon,rooms}=helpers;const room=state.room;const previous=state.roomPlans[room]||{};
root.innerHTML=`<section class="planner-intro"><div><div class="eyebrow">MEASURE FIRST. MAKE IT YOURS.</div><h2>讓每件家具，都剛剛好。</h2><p>上傳平面圖，標定比例並圈出房間；或直接輸入室內淨長寬，取得適合空間的家具與燈具建議。</p></div><span class="privacy-pill">圖片僅在你的瀏覽器處理</span></section><div class="room-saved" aria-label="空間用途">${rooms.filter(r=>r.id!=='all').map(r=>`<button data-room="${r.id}" class="${room===r.id?'active':''}">${r.name}${state.roomPlans[r.id]?' · 已規劃':''}</button>`).join('')}</div><div class="planner-layout"><section class="plan-card"><div class="step-label">01 / YOUR FLOOR PLAN</div><h3>上傳租屋處平面圖</h3><label class="upload-box" id="dropzone" ${uploaded?'hidden':''}><input class="file-input" id="floor-file" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"><span>${icon('upload')}</span><strong>把平面圖放在這裡</strong><p>拖曳上傳，或從裝置選擇<br>JPG、PNG、WebP、PDF · 最大 10 MB</p><span class="upload-cta">選擇平面圖</span></label><p id="upload-error" class="upload-error" role="alert"></p><div id="loaded-plan" ${uploaded?'':'hidden'}><div class="plan-toolbar"><span id="file-name">${uploaded?esc(uploaded.name):''}</span><div><button class="text-button" id="replace-image">換一張</button> <button class="text-button" id="remove-image">移除</button></div></div><div class="plan-image-wrap"><img id="floor-image" ${uploaded?`src="${uploaded.url}"`:''} alt="你上傳的租屋平面圖"><canvas id="plan-canvas" tabindex="0" aria-label="先點選已知長度的兩端，再圈選房間；也可使用右側尺寸輸入。"></canvas></div><div class="plan-mode-buttons"><button data-plan-mode="scale" class="${mode==='scale'?'active':''}">1. 點選已知長度兩端</button><button data-plan-mode="room" ${scale?'':'disabled'} class="${mode==='room'?'active':''}">2. 點選房間對角</button></div><div class="calibration-controls"><div><label for="reference-length">這段長度實際是幾公尺？</label><input id="reference-length" type="number" min="0.1" max="100" step="0.01" placeholder="例如 3.6"></div><button id="apply-scale">套用比例</button></div><p id="plan-status" role="status">${scale?'比例已設定。點選「房間對角」，在室內範圍點兩次。':'先在圖上點出一段已知長度的兩端，再輸入其公尺數。'}</p></div><p class="plan-help">沒有平面圖也可以直接輸入尺寸。照片若有透視變形，請以捲尺實測為準。PDF 僅使用第一頁；圖片在離開分頁後不會保留。</p></section><form id="room-form" class="room-form"><div class="step-label">02 / ROOM DETAILS</div><h3>${rooms.find(r=>r.id===room).name}的空間條件</h3><div class="field"><label for="dimension-unit">尺寸單位</label><select id="dimension-unit"><option value="m">公尺 m</option><option value="cm">公分 cm</option><option value="ft">英尺 ft</option></select></div><div class="field field-row"><div><label for="room-width">室內淨寬</label><input id="room-width" type="number" min="0.01" step="any" placeholder="例如 3.0" value="${Number.isFinite(previous.width)?previous.width:''}" required></div><div><label for="room-length">室內淨長</label><input id="room-length" type="number" min="0.01" step="any" placeholder="例如 3.6" value="${Number.isFinite(previous.length)?previous.length:''}" required></div></div><div class="field"><label for="occupants">使用人數</label><select id="occupants"><option value="1" ${previous.occupants!==2?'selected':''}>1 人</option><option value="2" ${previous.occupants===2?'selected':''}>2 人（共用床）</option></select></div><div class="field"><label for="person-height">使用者最高身高（cm）</label><input id="person-height" type="number" min="100" max="230" value="${Number.isFinite(previous.height)?previous.height:170}" required></div><div class="field"><label for="room-light">白天自然採光</label><select id="room-light"><option value="bright" ${previous.light==='bright'?'selected':''}>充足</option><option value="dim" ${!previous.light||previous.light==='dim'?'selected':''}>偏少</option><option value="none" ${previous.light==='none'?'selected':''}>沒有自然光</option></select></div><button class="primary-button" type="submit">產生適合我的建議 ↗</button><p id="room-error" class="input-error" role="alert"></p><p class="fine" id="dimension-source" data-source="${previous.source==='plan'?'plan':'manual'}">${previous.source==='plan'?'上次尺寸來自平面圖標定。':'以空房矩形範圍初估；已有家具請先扣除佔用空間。'}</p></form></div><div id="room-results"></div>`;
root.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{location.hash=`customize/${b.dataset.room}`});$('#floor-file').onchange=e=>loadFile(e.target.files?.[0]);const drop=$('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');loadFile(e.dataTransfer.files?.[0])};$('#replace-image').onclick=()=>$('#floor-file').click();$('#remove-image').onclick=()=>{if(uploaded)URL.revokeObjectURL(uploaded.url);uploaded=null;scale=null;boxes={};points=[];mode='scale';renderPlanner(root,state,helpers)};
root.querySelectorAll('[data-plan-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.planMode;points=[];updateMode();draw()});$('#apply-scale').onclick=applyScale;$('#room-form').onsubmit=e=>{e.preventDefault();generate()};$('#dimension-unit').onchange=e=>{const old=e.target.dataset.previous||'m',next=e.target.value,factors={m:1,cm:.01,ft:.3048};for(const id of ['#room-width','#room-length']){const input=$(id);if(input.value)input.value=String(Number((Number(input.value)*factors[old]/factors[next]).toFixed(3)))}e.target.dataset.previous=next};for(const id of ['#room-width','#room-length'])$(id).oninput=()=>{$('#dimension-source').textContent='尺寸已手動輸入；可重新產生建議。';$('#dimension-source').dataset.source='manual'};
$('#plan-canvas').onclick=onPoint;$('#plan-canvas').onkeydown=e=>{if(e.key==='Escape'){points=[];draw();$('#plan-status').textContent='已取消目前標記，請重新點選。'}};$('#floor-image').onload=()=>{draw();if(observer)observer.disconnect();observer=new ResizeObserver(draw);observer.observe($('#floor-image'))};if(uploaded&&$('#floor-image').complete)draw();if(previous.width&&previous.length){try{renderResults(previous)}catch{}}
}
async function loadFile(file){if(!file)return;$('#upload-error').textContent='';if(file.size>10*1024*1024){$('#upload-error').textContent='檔案超過 10 MB，請縮小後重新上傳。';return}if(!['image/png','image/jpeg','image/webp','application/pdf'].includes(file.type)){$('#upload-error').textContent='請使用 JPG、PNG、WebP 圖片或 PDF。';return}let nextUrl;try{if(file.type==='application/pdf'){$('#upload-error').textContent='正在讀取 PDF 第一頁…';const pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='./vendor/pdf.worker.mjs';const task=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false});const pdf=await task.promise;try{const page=await pdf.getPage(1),v=page.getViewport({scale:1});const viewport=page.getViewport({scale:Math.min(2,1600/Math.max(v.width,v.height))});const canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();nextUrl=URL.createObjectURL(blob)}finally{await pdf.destroy()}}else nextUrl=URL.createObjectURL(file);
const img=new Image();img.src=nextUrl;await img.decode();if(img.naturalWidth>16000||img.naturalHeight>16000||img.naturalWidth*img.naturalHeight>40000000)throw Error('oversized');if(uploaded)URL.revokeObjectURL(uploaded.url);uploaded={url:nextUrl,name:file.name,width:img.naturalWidth,height:img.naturalHeight};scale=null;mode='scale';points=[];boxes={};renderPlanner(root,state,helpers);helpers.toast('平面圖已載入。先標定一段已知長度。');}catch(error){if(nextUrl)URL.revokeObjectURL(nextUrl);$('#upload-error').textContent=error.message==='oversized'?'圖片解析度過高，請縮小到 4,000 萬像素以下。':'無法讀取這個檔案。請使用未加密的 PDF 或重新匯出的圖片。';}}
function updateMode(){root.querySelectorAll('[data-plan-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.planMode===mode);b.disabled=b.dataset.planMode==='room'&&!scale});$('#plan-status').textContent=mode==='scale'?'在圖上點選已知長度的兩端；按 Esc 可取消。':'在房間室內範圍點選左上角與右下角；不包含牆厚。'}
function onPoint(event){if(!uploaded)return;const rect=$('#plan-canvas').getBoundingClientRect();points.push({x:(event.clientX-rect.left)/rect.width,y:(event.clientY-rect.top)/rect.height});if(points.length>2)points=[points[2]];if(mode==='room'&&points.length===2){const w=Math.abs(points[1].x-points[0].x)*uploaded.width/scale,l=Math.abs(points[1].y-points[0].y)*uploaded.height/scale;if(w<1||l<1||w>20||l>20){$('#plan-status').textContent='標記範圍不在 1–20 公尺內，請重新確認比例或圈選範圍。';points=[];draw();return}boxes[state.room]={x:Math.min(points[0].x,points[1].x),y:Math.min(points[0].y,points[1].y),w:Math.abs(points[1].x-points[0].x),h:Math.abs(points[1].y-points[0].y)};$('#dimension-unit').value='m';$('#dimension-unit').dataset.previous='m';$('#room-width').value=w.toFixed(2);$('#room-length').value=l.toFixed(2);$('#dimension-source').dataset.source='plan';$('#dimension-source').textContent='尺寸來自這張平面圖的比例與圈選範圍。';$('#plan-status').textContent=`已量得約 ${w.toFixed(2)} × ${l.toFixed(2)} m。確認後點「產生適合我的建議」。`;points=[]}else $('#plan-status').textContent=points.length===1?'已記錄第一點，請選第二點。':mode==='scale'?'已記錄兩端，輸入實際公尺數並套用比例。':'已記錄範圍。';draw()}
function applyScale(){const real=Number($('#reference-length').value);if(mode!=='scale'||points.length!==2||!Number.isFinite(real)||real<.1||real>100){$('#plan-status').textContent='請先選取兩個端點，並輸入 0.1–100 公尺的已知長度。';return}const px=Math.hypot((points[1].x-points[0].x)*uploaded.width,(points[1].y-points[0].y)*uploaded.height);if(px<uploaded.width*.01){$('#plan-status').textContent='兩點距離太近，請選較長且清楚的一段。';return}scale=px/real;boxes={};mode='room';points=[];updateMode();draw();helpers.toast('比例已設定，現在圈出房間範圍。')}
function draw(){const canvas=$('#plan-canvas');if(!canvas||!uploaded)return;canvas.width=uploaded.width;canvas.height=uploaded.height;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,line=Math.max(2,w/300);ctx.lineWidth=line;ctx.strokeStyle='#194f45';ctx.fillStyle='#194f4520';for(const [room,b] of Object.entries(boxes)){ctx.fillRect(b.x*w,b.y*h,b.w*w,b.h*h);ctx.strokeRect(b.x*w,b.y*h,b.w*w,b.h*h);ctx.font=`${Math.max(14,w/40)}px sans-serif`;ctx.fillStyle='#194f45';ctx.fillText(helpers.rooms.find(r=>r.id===room).name,b.x*w+8,b.y*h+Math.max(24,w/30));ctx.fillStyle='#194f4520'}ctx.strokeStyle='#d37539';ctx.fillStyle='#d37539';for(const p of points){ctx.beginPath();ctx.arc(p.x*w,p.y*h,Math.max(4,w/130),0,Math.PI*2);ctx.fill()}if(points.length===2){ctx.beginPath();ctx.moveTo(points[0].x*w,points[0].y*h);ctx.lineTo(points[1].x*w,points[1].y*h);ctx.stroke()}}
function generate(){const factors={m:1,cm:.01,ft:.3048},factor=factors[$('#dimension-unit').value];const plan={width:Number($('#room-width').value)*factor,length:Number($('#room-length').value)*factor,room:state.room,occupants:Number($('#occupants').value),height:Number($('#person-height').value),light:$('#room-light').value,source:$('#dimension-source').dataset.source||'manual'};try{analyze(plan);state.roomPlans[state.room]=plan;helpers.persist();$('#room-error').textContent='';renderResults(plan);helpers.toast('已依房間尺寸更新建議。');$('#room-results').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}catch(error){$('#room-error').textContent=error.message}}
function renderResults(plan){const {area,results,furniture}=analyze(plan),{esc,rooms,products,searchUrl}=helpers;const room=rooms.find(r=>r.id===plan.room);const viewW=plan.width*100,viewH=plan.length*100;const shape=furniture?`<rect x="${30+furniture.x*100}" y="${30+furniture.y*100}" width="${furniture.w*100}" height="${furniture.l*100}" rx="4" fill="#d7e7bb" stroke="#799663" stroke-width="2"/><text x="${30+furniture.w*50}" y="${30+furniture.l*50}" text-anchor="middle" font-size="12" fill="#194f45">${furniture.label}</text>`:'';
$('#room-results').innerHTML=`<section class="recommendation-panel"><div class="eyebrow">YOUR SPACE, YOUR SHORTLIST</div><h2>${room.name} · ${area.toFixed(1)} m² 的配置建議</h2><p>依 ${plan.width.toFixed(2)} × ${plan.length.toFixed(2)} m、${plan.occupants} 人及採光條件估算。${plan.source==='plan'?'尺寸來自你標定的平面圖。':'尺寸來自手動輸入。'}</p><div class="recommendation-grid">${results.map(r=>{const product=products.find(p=>p.id===r.product);return `<article class="recommendation"><span class="eyebrow">${r.type==='light'?'LIGHTING':r.type==='bed'?'SLEEP WELL':'SPACE ESSENTIALS'}</span><h3>${r.title}</h3><strong class="metric">${r.metric}</strong><p>${r.description}</p>${product?`<a href="${product.url}" target="_blank" rel="noopener noreferrer">查看 ${product.store} ${product.name} ↗</a>`:''}${r.query?`<details class="recommended-stores"><summary>${product?'比較其他商店':'依建議規格找商品'}</summary>${['Amazon','Target','Walmart','IKEA'].map(store=>`<a href="${searchUrl(store,r.query)}" target="_blank" rel="noopener noreferrer">搜尋 ${store} ↗</a>`).join('')}</details>`:''}</article>`}).join('')}</div><div class="layout-diagram"><svg role="img" aria-label="${esc(room.name)}矩形範圍與候選家具佔地示意，未包含門窗" viewBox="0 0 ${viewW+60} ${viewH+70}"><rect x="30" y="30" width="${viewW}" height="${viewH}" fill="white" stroke="#194f45" stroke-width="3"/>${shape}<text x="${viewW/2+30}" y="19" text-anchor="middle" font-size="13" fill="#66785d">${plan.width.toFixed(2)} m</text><text transform="translate(15 ${viewH/2+30}) rotate(-90)" text-anchor="middle" font-size="13" fill="#66785d">${plan.length.toFixed(2)} m</text><text x="${viewW/2+30}" y="${viewH+54}" text-anchor="middle" font-size="11" fill="#809272">候選家具佔地示意 · 非完整配置圖</text></svg></div><p class="planner-note">推薦依矩形尺寸與預留動線計算，沒有自動辨識門窗、插座、固定設備或承重牆。床架仍以實際外徑為準；購買前確認門扇迴轉、搬運路線及租屋規範。照明為規劃起點，並非現場照度測量。</p><a class="detail-primary" href="#general/${plan.room}">查看${room.name}完整採買清單 ↗</a></section>`;
}
